import { Component, type ErrorInfo, type ReactNode } from "react";

interface Props {
  children: ReactNode;
  fallback?: (error: Error, reset: () => void) => ReactNode;
  onError?: (error: Error, info: ErrorInfo) => void;
}

interface State {
  error: Error | null;
  componentStack: string | null;
}

export class ErrorBoundary extends Component<Props, State> {
  state: State = { error: null, componentStack: null };

  static getDerivedStateFromError(error: Error): Partial<State> {
    return { error };
  }

  componentDidCatch(error: Error, info: ErrorInfo): void {
    const stack = info.componentStack ?? null;
    this.setState({ componentStack: stack });

    if (this.props.onError) {
      this.props.onError(error, info);
    } else {
      console.error("[ErrorBoundary] Uncaught render error:", error.message);
      console.error("[ErrorBoundary] Component stack:", stack);
      console.error(error);
    }
  }

  reset = (): void => {
    this.setState({ error: null, componentStack: null });
  };

  render(): ReactNode {
    const { error, componentStack } = this.state;

    if (error) {
      if (this.props.fallback) {
        return this.props.fallback(error, this.reset);
      }

      return (
        <div
          role="alert"
          style={{
            padding: "1rem",
            border: "1px solid #f87171",
            borderRadius: "0.375rem",
            backgroundColor: "#fef2f2",
          }}
        >
          <h2 style={{ margin: "0 0 0.5rem", color: "#b91c1c" }}>
            Something went wrong
          </h2>
          <pre
            style={{
              margin: "0 0 0.75rem",
              whiteSpace: "pre-wrap",
              fontSize: "0.875rem",
              color: "#7f1d1d",
            }}
          >
            {error.message}
          </pre>
          {process.env.NODE_ENV !== "production" && componentStack && (
            <details style={{ marginBottom: "0.75rem" }}>
              <summary
                style={{ cursor: "pointer", fontSize: "0.75rem", color: "#991b1b" }}
              >
                Component stack
              </summary>
              <pre
                style={{
                  marginTop: "0.25rem",
                  fontSize: "0.75rem",
                  whiteSpace: "pre-wrap",
                  color: "#7f1d1d",
                }}
              >
                {componentStack}
              </pre>
            </details>
          )}
          <button
            onClick={this.reset}
            style={{
              padding: "0.375rem 0.75rem",
              backgroundColor: "#dc2626",
              color: "#fff",
              border: "none",
              borderRadius: "0.25rem",
              cursor: "pointer",
              fontSize: "0.875rem",
            }}
          >
            Try Again
          </button>
        </div>
      );
    }

    return this.props.children;
  }
}

